<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class ProductBooking {
 public static function register(): void { add_shortcode('avanik_product_checkout',[self::class,'render']); add_action('admin_post_avanik_product_checkout',[self::class,'checkout']); }
 public static function render(): string { if(!is_user_logged_in())return '<p>برای رزرو ابتدا وارد حساب کاربری شوید.</p>'; $id=absint($_GET['product_id']??0); global $wpdb; $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.ProductRepository::table_name().' WHERE id=%d AND status=%s',$id,Product::PUBLISHED),ARRAY_A); if(!$p)return '<p>محصول قابل رزرو نیست.</p>'; $max=max(1,(int)$p['capacity']); ob_start(); ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" dir="rtl"><input type="hidden" name="action" value="avanik_product_checkout"><input type="hidden" name="product_id" value="<?php echo esc_attr($id); ?>"><?php wp_nonce_field('avanik_product_checkout'); ?><p><label>تعداد<br><input type="number" name="quantity" min="1" max="<?php echo esc_attr($max); ?>" value="1" required></label></p><p><label>نام مسافر<br><input name="passenger_name" required></label></p><p><label>موبایل<br><input name="passenger_phone" required></label></p><p><label>ایمیل<br><input type="email" name="passenger_email"></label></p><h3>روش پرداخت</h3><label><input type="radio" name="payment_gateway" value="manual" checked> کارت به کارت</label> <label><input type="radio" name="payment_gateway" value="zarinpal"> زرین‌پال</label><p><button type="submit">ثبت رزرو و ادامه پرداخت</button></p></form><?php return (string)ob_get_clean(); }
 public static function checkout(): void { if(!is_user_logged_in()||!check_admin_referer('avanik_product_checkout'))wp_die('Unauthorized'); global $wpdb; $id=absint($_POST['product_id']??0); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.ProductRepository::table_name().' WHERE id=%d AND status=%s',$id,Product::PUBLISHED),ARRAY_A); if(!$p)wp_die('Product unavailable'); $qty=max(1,absint($_POST['quantity']??1)); if((int)$p['capacity']>0&&$qty>(int)$p['capacity'])wp_die('ظرفیت کافی نیست.'); $meta=json_decode((string)$p['metadata'],true)?:[]; $booking=BookingRepository::create(['customer_id'=>get_current_user_id(),'product_id'=>$id,'booking_type'=>$p['type'],'destination'=>$meta['destination']??'','travel_date'=>$meta['start_date']??'','quantity'=>$qty,'passenger_name'=>$_POST['passenger_name']??'','passenger_phone'=>$_POST['passenger_phone']??'','passenger_email'=>$_POST['passenger_email']??'','total_amount'=>(float)$p['price']*$qty]); if(!$booking)wp_die('رزرو ایجاد نشد.'); $gateway=sanitize_key($_POST['payment_gateway']??'manual'); $payment=PaymentService::initialize(['booking_id'=>$booking,'customer_id'=>get_current_user_id(),'amount'=>(float)$p['price']*$qty,'currency'=>$p['currency'],'gateway'=>$gateway]); if(is_wp_error($payment))wp_die($payment->get_error_message()); wp_safe_redirect(home_url('/payment/?transaction_id='.rawurlencode($payment['transaction_id']))); exit; }
}